-- V543: the College of Health Sciences' 2025/2026 school fees stated on the portal, from the approved workbook.
--
-- "FEES STRUCTURE FOR 2025/2026 ACADEMIC SESSION", College of Health Sciences, Office of the Finance Controller (prepared by the
-- Students Account Officer, authorized by the Ag. Finance Controller): PAGE 1 — MBBS, Nursing, Human Anatomy, Human Physiology;
-- PAGE 2 — Radiography, Biochemistry, Medical Laboratory Science. Every College programme sits under faculty BAMS with fees of its
-- own, and on the live-shaped copy 2025/2026 stated none of them: 8,239 of the College's students had no school fee stated.
--
-- The 364 lines are the workbook as the Fee Setup upload reads it (lib/fee-matrix.ts, V535): each block charged to its programme;
-- "100L/200DE" level 100 for UTME and Transfer and level 200 for Direct Entry, "200L" UTME and Transfer, 300L and up all three,
-- "/SP" the spillover line too; each band's TOTAL row split between the semesters as the sheet splits it, the second semester the
-- TOTAL less the first (the Radiography and Medical Laboratory 100L/200DE cells whose 1ST and 2ND did not make the TOTAL take the
-- TOTAL, as the Bursary decided on 17 Oct 2026). The same 364 lines as the "fees to state" sheet delivered that day.
--
-- Loaded only on a database with live students of the College (not a fresh test database), and only where nothing of the
-- College's is stated for 2025/2026 — no line of the seven programmes and no line of faculty BAMS
-- of its own — and only the College's lines are written (finance.import_fee_structure, scope LISTED): every other faculty's lines
-- stand. Otherwise nothing is written and the migration says why. Radiography 500 Level has no amount on the workbook and is left
-- without a line (81 students on the copy) until the Bursary states it.

BEGIN;

SELECT set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
SELECT set_config('moaum.actor_office', 'bursar', true);
SELECT set_config('moaum.reason', 'V543: the College of Health Sciences 2025/2026 fees from the approved workbook (FEES STRUCTURE FOR 2025/2026, Office of the Finance Controller)', true);

DO $v543$
DECLARE r record; v_programme_lines int; v_faculty_lines int; v_programmes int;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM policy.academic_session WHERE name = '2025/2026') THEN
        RAISE NOTICE 'V543: there is no 2025/2026 session here; nothing loaded';
        RETURN;
    END IF;
    SELECT count(*) INTO v_programmes FROM ref.programme WHERE code IN ('C00061', 'C18115', 'C29132', 'C35147', 'C49411', 'C49412', 'C64548');
    IF v_programmes < 7 THEN
        RAISE NOTICE 'V543: % of the College''s 7 programmes are on the register here; nothing loaded', v_programmes;
        RETURN;
    END IF;
    -- a database with no student of the College (a fresh test database, CI) is not the portal's: nothing is stated there
    IF NOT EXISTS (SELECT 1 FROM people.student WHERE programme_code IN ('C00061', 'C18115', 'C29132', 'C35147', 'C49411', 'C49412', 'C64548') AND status IN ('ADMITTED', 'ACTIVE', 'PROBATION')) THEN
        RAISE NOTICE 'V543: no live student of the College here; nothing loaded';
        RETURN;
    END IF;
    SELECT count(*) INTO v_programme_lines FROM finance.fee_schedule
     WHERE session = '2025/2026' AND ended_at IS NULL AND programme_code IN ('C00061', 'C18115', 'C29132', 'C35147', 'C49411', 'C49412', 'C64548');
    SELECT count(*) INTO v_faculty_lines FROM finance.fee_schedule
     WHERE session = '2025/2026' AND ended_at IS NULL AND faculty_code = 'BAMS' AND programme_code IS NULL AND entry_mode IS DISTINCT FROM 'CCE';
    IF v_programme_lines > 0 OR v_faculty_lines > 0 THEN
        RAISE NOTICE 'V543: the College''s 2025/2026 fees are stated already (% programme lines, % faculty lines); nothing loaded', v_programme_lines, v_faculty_lines;
        RETURN;
    END IF;
